/mcp-server/gui/chunk-renderer.ts:
  887:  * formatter on `formatWriteTodosDetail` for the general case.
  889: function formatWriteTodosDetail(args: unknown): string[] {
  1056:     return formatWriteTodosDetail(args);

876	 * **Return-shape divergence from sibling formatters.**
877	 * Unlike `formatFileToolDetail`, `formatExecuteDetail`, `formatTaskDetail`, and
878	 * `formatLedgerToolDetail` — which all return `'↳ …'`-prefixed strings —
879	 * this function returns raw Markdown list items (`'- [x] …'` / `'- [ ] …'`).
880	 *
881	 * This is intentional: `write_todos` renders a visual checklist, not a
882	 * summary line.  The `getToolDetailLines` dispatcher pushes return values
883	 * verbatim into the output line buffer, so the rendered Markdown is correct.
884	 *
885	 * If you add a new formatter to this family, follow the `'↳ …'` convention
886	 * unless the tool's output is inherently list-shaped.  Do **not** model a new
887	 * formatter on `formatWriteTodosDetail` for the general case.
888	 */
889	function formatWriteTodosDetail(args: unknown): string[] {
890	  if (!args || typeof args !== 'object' || Array.isArray(args)) return [];
891	  const a = args as Record<string, unknown>;
892	  const todos = a['todos'];
893	  if (!Array.isArray(todos) || todos.length === 0) return [];
894	
895	  return todos.map((todo: unknown) => {
896	    if (!todo || typeof todo !== 'object' || Array.isArray(todo)) return '- [ ] (unknown)';
897	    const t = todo as Record<string, unknown>;
898	    const content = typeof t['content'] === 'string' ? t['content'] : '(unknown)';
899	    const status = typeof t['status'] === 'string' ? t['status'] : '';
900	    const checked = status === 'completed' ? 'x' : ' ';
901	    return `- [${checked}] ${content}`;
902	  });
903	}
